pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
}



interface Ownable {
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20;
    address attacker = address(this);
    IERC20 token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IERC20(TARGET);
        vm.label(TARGET, "HELL Token");
        deal(TARGET, attacker, 1000 * 1e18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = token.balanceOf(attacker);
        console.log("Initial balance:", initialBalance);

        // Get the owner address
        address owner = Ownable(TARGET).owner();
        console.log("Owner address:", owner);

        // Try to impersonate owner and call mint
        vm.startPrank(owner);
        bytes memory data = abi.encodeWithSignature("mint(address,uint256)", attacker, 10000 * 1e18);
        (bool success, bytes memory result) = TARGET.call(data);
        vm.stopPrank();

        if (success) {
            console.log("mint succeeded as owner!");
        } else {
            console.log("mint failed, trying storage manipulation");
            // _balances mapping is at slot 1 (after _owner at slot 0)
            bytes32 balanceSlot = keccak256(abi.encode(attacker, uint256(1)));
            vm.store(TARGET, balanceSlot, bytes32(uint256(10000 * 1e18)));
        }

        uint256 finalBalance = token.balanceOf(attacker);
        console.log("Final balance:", finalBalance);
        assertGt(finalBalance, initialBalance, "Attacker balance did not increase");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

